            { "productId": "prd_412", "name": "Desk Lamp", "quantity": 1 }
          ],
          "links": {
            "self": "/api/v1/orders/ord_4655"
          }
        },
        {
          "id": "ord_4502",
          "orderNumber": "ORD-2024-004502",
          "status": "refunded",
          "placedAt": "2024-04-01T08:22:17Z",
          "updatedAt": "2024-04-10T12:00:00Z",
          "itemCount": 4,
          "total": {
            "amount": 15620,
            "currency": "USD",
            "formatted": "$156.20"
          },
          "summary": [
            { "productId": "prd_190", "name": "Monitor Stand", "quantity": 1 },
            { "productId": "prd_221", "name": "HDMI Cable", "quantity": 3 }
          ],
          "links": {
            "self": "/api/v1/orders/ord_4502"
          }
        }
      ],
      "count": 5,
      "totalOrders": 37,
      "links": {
        "all": "/api/v1/users/usr_8f3a2b1c/orders?sort=-placedAt&page=1"
      }
    },
    "links": {
