## 7. TypeScript contract (for generated clients / validation)

```ts
type Currency = string; // ISO 4217
type ISODateTime = string; // RFC 3339, UTC

interface ProfileWithOrdersResponse {
  user: User;
  orders: { items: Order[]; page: Page };
  links: { self: string; orders: string; nextOrdersPage?: string };
  meta: { requestId: string; generatedAt: ISODateTime };
}

interface User {
  id: string;
  email: string;
  displayName: string;
  avatarUrl: string | null;
  createdAt: ISODateTime;
  defaultCurrency: Currency;
  profile: {
    firstName?: string;
    lastName?: string;
    phone?: string;
    bio: string | null;
    locale?: string;
    timezone?: string;
  };
  addresses: Address[];
}

interface Address {
  id: string;
  label?: string;
  line1: string;
  line2: string | null;
  city: string;
  region?: string;
  postalCode: string;
  countryCode: string; // ISO 3166-1 alpha-2
  isDefaultShipping?: boolean;
  isDefaultBilling?: boolean;
}

type OrderStatus =
  | "pending" | "paid" | "processing"
  | "shipped" | "delivered" | "cancelled" | "refunded";

interface Order {
  id: string;
  number: string;
  status: OrderStatus;
  placedAt: ISODateTime;
  currency: Currency;
  itemCount: number;
  totals: {
    subtotal: number; discount: number; shipping: number;
    tax: number; grandTotal: number;
  };
  items: OrderLine[];
  fulfillment?: Fulfillment;
  payment: Payment;
  shippingAddress?: Address;
  billingAddress?: Address;
  cancelledAt?: ISODateTime;
  links: { self: string; invoice?: string };
}

interface OrderLine {
  lineId: string;
  productId: string;
  sku: string;
  name: string;
  quantity: number;
  unitPrice: number;
  lineTotal: number;
  imageUrl?: string;
  options: { name: string; value: string }[];
}

interface Fulfillment {
  status: "unfulfilled" | "in_transit" | "out_for_delivery" | "delivered";
  carrier?: string;
  trackingNumber?: string;
  trackingUrl?: string;
  shippedAt?: ISODateTime;
  estimatedDeliveryAt?: ISODateTime;
}

interface Payment {
  status: "pending" | "authorized" | "captured" | "failed"
        | "partially_refunded" | "refunded";
  method: "card" | "paypal" | "bank_transfer" | "credit";
  brand?: string;
  last4?: string;
  capturedAt?: ISODateTime;
  refundedAmount?: number;
}

interface Page {
  limit: number;
  count: number;
  hasMore: boolean;
  nextCursor: string | null;
}
```

