  type: TType;
  api_version: string;
  created_at: string; // RFC 3339
  livemode: boolean;
  delivery: { id: string; attempt: number; max_attempts: number };
  data: TData;
  links: Record<string, string>;
}

interface SubscriptionRenewedData {
  object: {
    id: string;
    object: "subscription";
    status: "active" | "trialing" | "past_due" | "canceled";
    customer: { id: string; email: string | null; name: string | null };
    plan: {
      id: string;
      name: string;
      interval: "day" | "week" | "month" | "year";
      interval_count: number;
      amount: MinorUnit;
      currency: string; // ISO 4217 lowercase
    };
    quantity: number;
    billing_cycle_anchor: string;
    current_period_start: string;
    current_period_end: string;
    next_billing_date: string | null;
    renewal: {
      number: number;
      billing_reason:
        | "subscription_cycle"
        | "trial_conversion"
        | "manual"
        | "proration";
      prorated: boolean;
      previous_plan_id: string | null;
      discount: { id: string; percent_off?: number; amount_off?: MinorUnit } | null;
    };
    payment: {
      status: "succeeded" | "failed" | "pending";
      invoice_id: string;
      payment_intent_id: string | null;
      amount_due: MinorUnit;
      amount_paid: MinorUnit;
      amount_refunded: MinorUnit;
      currency: string;
      paid_at: string | null;
      payment_method: {
        id: string;
        type: "card" | "bank_account" | "paypal" | "other";
        brand?: string;
        last4?: string;
        exp_month?: number;
        exp_year?: number;
      } | null;
      failure_code: string | null;
      failure_message: string | null;
    };
    trial_end: string | null;
    cancel_at_period_end: boolean;
    canceled_at: string | null;
    ended_at: string | null;
    metadata: Record<string, string>;
  };
}

type SubscriptionRenewedEvent = WebhookEvent<
  "subscription.renewed",
  SubscriptionRenewedData
>;
```

