## Example Handler

```ts
import { createHmac, timingSafeEqual } from "node:crypto";
import express from "express";

const SECRET = process.env.WEBHOOK_SECRET!;
const app = express();

app.post(
  "/webhooks/billing",
  express.raw({ type: "application/json" }), // raw body for signature
  async (req, res) => {
    // --- 1. Verify signature ---
    const header = req.get("Webhook-Signature") ?? "";
    const parts = Object.fromEntries(
      header.split(",").map((p) => p.split("=") as [string, string])
    );
    const timestamp = parts.t;
    if (!timestamp || Math.abs(Date.now() / 1000 - Number(timestamp)) > 300) {
      return res.status(400).send("stale timestamp");
    }
    const expected = createHmac("sha256", SECRET)
      .update(`${timestamp}.${req.body}`)
      .digest("hex");
    const a = Buffer.from(expected);
    const b = Buffer.from(parts.v1 ?? "");
    if (a.length !== b.length || !timingSafeEqual(a, b)) {
      return res.status(401).send("bad signature");
    }

    // --- 2. Parse & dedupe ---
    const event: SubscriptionRenewedEvent = JSON.parse(req.body.toString());
    const fresh = await redis.set(`evt:${event.id}`, "1", "NX", "EX", 86400);
    if (!fresh) return res.status(200).send("duplicate ignored");

    // --- 3. Enqueue for async processing, ack fast ---
    await queue.push("billing.renewed", event);
    res.status(200).send("ok");
  }
);
```

